//! Immutable runtime image shader. Authoring interfaces remain provider-owned.
use serde::{Deserialize, Serialize};
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct Program {
    /// WGSL declarations including `fn effect(uv: vec2<f32>) -> vec4<f32>`.
    pub source: String,
    pub images: Vec<String>,
    /// Packed vec4 parameters; names/bindings are generated by the authoring provider.
    pub values: Vec<[f32; 4]>,
    pub logical_size: [f32; 2],
    pub time: f32,
    pub progress: f32,
}
impl Program {
    pub fn validate(&self) -> Result<(), String> {
        let mut names = std::collections::BTreeSet::new();
        if self.source.len() > 65536
            || self.source.is_empty()
            || self.images.len() > 8
            || self.values.len() > 32
            || self
                .values
                .iter()
                .flatten()
                .chain(&self.logical_size)
                .chain([&self.time, &self.progress])
                .any(|v| !v.is_finite())
            || self.logical_size.iter().any(|v| *v <= 0.)
        {
            return Err(
                "Shader exceeds source/input/parameter limits or has invalid values".into(),
            );
        }
        for name in &self.images {
            if name.is_empty()
                || name.len() > 64
                || name.starts_with("fold_")
                || !name.bytes().enumerate().all(|(i, c)| {
                    c.is_ascii_alphabetic() || c == b'_' || (i > 0 && c.is_ascii_digit())
                })
                || !names.insert(name)
            {
                return Err("Shader image names must be unique WGSL identifiers".into());
            }
        }
        Ok(())
    }
    pub fn wgsl(&self) -> Result<String, String> {
        self.validate()?;
        let mut source = String::from(
            "struct FoldParams { size:vec4<f32>, clock:vec4<f32>, values:array<vec4<f32>,32>, };\n@group(0) @binding(0) var<uniform> fold_params:FoldParams;\n@group(0) @binding(1) var fold_output:texture_storage_2d<rgba32float,write>;\n@group(0) @binding(2) var<storage,read_write> fold_status:atomic<u32>;\n",
        );
        for (i, name) in self.images.iter().enumerate() {
            source.push_str(&format!("@group(0) @binding({}) var fold_image_{i}:texture_2d<f32>;\nfn {name}(uv:vec2<f32>)->vec4<f32>{{ let size=vec2<i32>(textureDimensions(fold_image_{i})); let p=vec2<i32>(floor(uv*vec2<f32>(size))); if(any(p<vec2<i32>(0)) || any(p>=size)){{return vec4<f32>(0.);}} return textureLoad(fold_image_{i},p,0); }}\n",i+3));
        }
        source.push_str(&self.source);
        source.push_str("\n@compute @workgroup_size(8,8) fn fold_main(@builtin(global_invocation_id) id:vec3<u32>){ let size=textureDimensions(fold_output); if(any(id.xy>=size)){return;} let uv=(vec2<f32>(id.xy)+vec2<f32>(0.5))/vec2<f32>(size); let color=effect(uv); if(any(color!=color) || any(abs(color)>vec4<f32>(3.402823e38)) || color.a<0. || color.a>1.){atomicOr(&fold_status,1u);} textureStore(fold_output,vec2<i32>(id.xy),color); }");
        Ok(source)
    }
}

fn no_loops(block: &naga::Block) -> Result<(), String> {
    use naga::Statement;
    for statement in block.iter() {
        match statement {
            Statement::Loop { .. } => {
                return Err("Live image shaders require loop-free code; use graph blur/multipass operators for kernels".into());
            }
            Statement::Block(block) => no_loops(block)?,
            Statement::If { accept, reject, .. } => {
                no_loops(accept)?;
                no_loops(reject)?;
            }
            Statement::Switch { cases, .. } => {
                for case in cases {
                    no_loops(&case.body)?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

impl Program {
    /// Device-independent source validation; callers run this on a worker before
    /// publishing a new source revision. GPU pipeline validation still applies.
    pub fn validate_source(&self) -> Result<(), String> {
        let source = self.wgsl()?;
        let module =
            naga::front::wgsl::parse_str(&source).map_err(|e| e.emit_to_string(&source))?;
        naga::valid::Validator::new(
            naga::valid::ValidationFlags::all(),
            naga::valid::Capabilities::default(),
        )
        .validate(&module)
        .map_err(|e| e.to_string())?;
        let mut layouts = naga::proc::Layouter::default();
        layouts.update(module.to_ctx()).map_err(|e| e.to_string())?;
        if module.types.iter().any(|(id, _)| layouts[id].size > 65536) {
            return Err(
                "Shader value types are limited to 64 KiB; use image inputs for large data".into(),
            );
        }
        for (_, global) in module.global_variables.iter() {
            if let Some(binding) = &global.binding {
                let expected = match binding.binding {
                    0 => "fold_params".into(),
                    1 => "fold_output".into(),
                    2 => "fold_status".into(),
                    n => format!("fold_image_{}", n - 3),
                };
                if binding.group != 0
                    || binding.binding >= 3 + self.images.len() as u32
                    || global.name.as_deref() != Some(expected.as_str())
                {
                    return Err("Declare image inputs and controls through the shader interface; extra GPU bindings are unsupported".into());
                }
            } else if global.space == naga::AddressSpace::WorkGroup {
                return Err("Live image functions cannot allocate shared workgroup storage".into());
            }
        }
        for (_, function) in module.functions.iter() {
            no_loops(&function.body)?;
            for (_, expression) in function.expressions.iter() {
                if let naga::Expression::GlobalVariable(handle) = expression
                    && matches!(
                        module.global_variables[*handle].name.as_deref(),
                        Some("fold_output" | "fold_status")
                    )
                {
                    return Err("Return pixels from effect(); output and validation resources are renderer-owned".into());
                }
            }
        }
        if module.entry_points.len() != 1 {
            return Err("Provide an effect function, not a shader entry point".into());
        }
        Ok(())
    }
}
